#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    std::vector<bool> findAnswer(std::vector<int>& parent, std::string s) {
        int n = parent.size();
        std::vector<std::vector<int>> adj(n);
        for (int i = 1; i < n; ++i) {
            adj[parent[i]].push_back(i);
        }
        for (int i = 0; i < n; ++i) {
            std::sort(adj[i].begin(), adj[i].end());
        }

        std::string post_order = "";
        std::vector<int> L(n), R(n);

        auto dfs = [&](auto& self, int u) -> void {
            int l_idx = post_order.size();
            for (int v : adj[u]) self(self, v);
            post_order.push_back(s[u]);
            int r_idx = post_order.size() - 1;
            L[u] = l_idx;
            R[u] = r_idx;
        };
        dfs(dfs, 0);

        std::string t = "#";
        for (char ch : post_order) {
            t.push_back(ch);
            t.push_back('#');
        }

        int m_len = t.size();
        std::vector<int> P(m_len, 0);
        int c = 0, r = 0;
        for (int i = 0; i < m_len; ++i) {
            int i_mirror = 2 * c - i;
            if (i < r) P[i] = std::min(r - i, P[i_mirror]);
            while (i - P[i] - 1 >= 0 && i + P[i] + 1 < m_len && t[i - P[i] - 1] == t[i + P[i] + 1]) {
                P[i]++;
            }
            if (i + P[i] > r) {
                c = i;
                r = i + P[i];
            }
        }

        std::vector<bool> ans(n, false);
        for (int i = 0; i < n; ++i) {
            int l = L[i], right = R[i];
            int center = (l + right) + 1;
            int span = right - l + 1;
            if (P[center] >= span) ans[i] = true;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private List<List<Integer>> adj;
    private StringBuilder postOrder = new StringBuilder();
    private int[] L, R;

    public boolean[] findAnswer(int[] parent, String s) {
        int n = parent.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 1; i < n; i++) adj.get(parent[i]).add(i);
        for (int i = 0; i < n; i++) Collections.sort(adj.get(i));

        L = new int[n];
        R = new int[n];
        dfs(0, s);

        char[] postStr = postOrder.toString().toCharArray();
        char[] t = new char[2 * n + 1];
        t[0] = '#';
        for (int i = 0; i < n; i++) {
            t[2 * i + 1] = postStr[i];
            t[2 * i + 2] = '#';
        }

        int mLen = t.length;
        int[] P = new int[mLen];
        int c = 0, r = 0;
        for (int i = 0; i < mLen; i++) {
            int iMirror = 2 * c - i;
            if (i < r) P[i] = Math.min(r - i, P[iMirror]);
            while (i - P[i] - 1 >= 0 && i + P[i] + 1 < mLen && t[i - P[i] - 1] == t[i + P[i] + 1]) {
                P[i]++;
            }
            if (i + P[i] > r) {
                c = i;
                r = i + P[i];
            }
        }

        boolean[] ans = new boolean[n];
        for (int i = 0; i < n; i++) {
            int left = L[i], right = R[i];
            int center = (left + right) + 1;
            int span = right - left + 1;
            if (P[center] >= span) ans[i] = true;
        }
        return ans;
    }

    private void dfs(int u, String s) {
        int lIdx = postOrder.length();
        for (int v : adj.get(u)) dfs(v, s);
        postOrder.append(s.charAt(u));
        int rIdx = postOrder.length() - 1;
        L[u] = lIdx;
        R[u] = rIdx;
    }
}

